def lire_socket(texte):
    ip, port = texte.rsplit(":", 1)
    if not port.isdigit() or int(port) > 65535:
        raise ValueError("port invalide")
    return [ip, int(port)]

RISQUES = {21: "FTP non chiffré", 23: "Telnet non chiffré", 3306: "base de données exposée", 3389: "bureau à distance exposé"}

def exposition(machines):
    lignes = []
    for nom in sorted(machines):
        for port in sorted(machines[nom]):
            if port in RISQUES:
                lignes.append(nom + " : " + str(port) + " (" + RISQUES[port] + ")")
    return lignes
